using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace ScreenCraft
{
    static class CoreRewriteTests
    {
        sealed class Picker:RegionPicker
        {
            internal Picker(Rectangle bounds,bool retain=false):base(Pixels(bounds.Size),bounds,new List<Grabber.Win>(),Mode.Image,false,retain){ModifierSource=delegate{return Keys.None;};}
            static Dib Pixels(Size size){var image=new Dib(size.Width,size.Height);using(var g=image.Graphics())g.Clear(Color.FromArgb(24,123,231));return image;}
            internal void Down(Point point){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,point.X,point.Y,0));}
            internal void MovePointer(Point point){OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,point.X,point.Y,0));}
            internal void Up(Point point){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,point.X,point.Y,0));}
            internal void Key(Keys key){OnKeyDown(new KeyEventArgs(key));}
            internal void LosePointer(){Capture=false;OnMouseCaptureChanged(EventArgs.Empty);}
        }
        sealed class Editor:Canvas
        {
            internal Editor():base(new Bitmap(600,400)){InPlaceViewport=true;Size=new Size(600,400);ModifierSource=delegate{return Keys.None;};}
            internal void Down(Point point){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,point.X,point.Y,0));}
            internal void MovePointer(Point point){OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,point.X,point.Y,0));}
            internal void Up(Point point){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,point.X,point.Y,0));}
            internal void LosePointer(){Capture=false;OnMouseCaptureChanged(EventArgs.Empty);}
            internal void Key(Keys keys){OnKeyDown(new KeyEventArgs(keys));}
        }
        internal static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("core/source assembly contains only ScreenCraft application types",delegate{var names=typeof(Canvas).Assembly.GetTypes().Select(t=>t.FullName??"").ToArray();check(!names.Any(n=>n.StartsWith("Stackshot.",StringComparison.Ordinal)),"legacy runtime type compiled");check(names.Any(n=>n=="ScreenCraft.Stitcher")&&names.Any(n=>n=="ScreenCraft.RegionPicker"),"replacement not compiled");});
            run("core/Bezier bounds include exact interior extrema",delegate{var shape=new Shape{Kind=Tool.Arrow,A=new PointF(0,0),B=new PointF(100,100),C=new PointF(300,-200),Curved=true};check(Math.Abs(shape.Box.Right-180)<.001&&Math.Abs(shape.Box.Top+80)<.001,"interior extremum missing");foreach(var point in shape.Curve(1000))check(point.X<=shape.Box.Right+.001&&point.Y>=shape.Box.Top-.001,"sample outside exact bounds");});
            run("core/rotation similarity preserves curved control point under quarter turn",delegate{var transformed=Painter.Similar(new PointF(50,25),PointF.Empty,new PointF(100,0),new PointF(10,20),new PointF(10,220));check(transformed==new PointF(-40,120),"control point rotation or scaling lost");});
            run("core/mosaic computes true block means and preserves source",delegate{using(var source=new Bitmap(2,2)){source.SetPixel(0,0,Color.Red);source.SetPixel(1,0,Color.Lime);source.SetPixel(0,1,Color.Blue);source.SetPixel(1,1,Color.White);using(var mosaic=Painter.Pixelate(source,new Rectangle(0,0,2,2),2)){for(int y=0;y<2;y++)for(int x=0;x<2;x++)check(mosaic.GetPixel(x,y).ToArgb()==Color.FromArgb(127,127,127).ToArgb(),"interpolated rather than average block");check(source.GetPixel(0,0).ToArgb()==Color.Red.ToArgb(),"source overwritten");}}});
            run("core/spotlight apertures overlap without dark seams and have antialiased corners",delegate{using(var image=new Bitmap(140,100)){using(var g=Graphics.FromImage(image)){g.Clear(Color.White);Painter.DrawSpotlights(g,new[]{new Shape{Kind=Tool.Spotlight,A=new PointF(20,20),B=new PointF(90,80),Width=3,EffectOpacity=70},new Shape{Kind=Tool.Spotlight,A=new PointF(60,20),B=new PointF(120,80),Width=3,EffectOpacity=70}},null,new RectangleF(0,0,140,100));}check(image.GetPixel(70,50).R==255&&image.GetPixel(5,5).R<90,"overlap darkened or surround not dimmed");int partial=0;for(int y=20;y<32;y++)for(int x=20;x<32;x++){int value=image.GetPixel(x,y).R;if(value>90&&value<250)partial++;}check(partial>0,"jagged spotlight edge");}});
            run("core/fast selection uses release coordinates on a negative desktop origin",delegate{using(var picker=new Picker(new Rectangle(-640,-300,320,220))){Rectangle accepted=Rectangle.Empty;picker.Accepted=delegate{accepted=picker.Result;};picker.Down(new Point(17,23));picker.Up(new Point(217,163));check(accepted==new Rectangle(-623,-277,200,140),"mouse-up or physical origin lost");}});
            run("core/reversed fast selection normalizes endpoints and clamps outside desktop",delegate{using(var picker=new Picker(new Rectangle(0,0,320,220))){Rectangle accepted=Rectangle.Empty;picker.Accepted=delegate{accepted=picker.Result;};picker.Down(new Point(210,170));picker.Up(new Point(-50,-30));check(accepted==new Rectangle(0,0,210,170),"reversed/clipped range wrong");}});
            run("core/lost selection capture never accepts an unfinished range",delegate{using(var picker=new Picker(new Rectangle(0,0,320,220))){int accepted=0;picker.Accepted=delegate{accepted++;};picker.Down(new Point(20,20));picker.MovePointer(new Point(160,130));picker.LosePointer();picker.Up(new Point(240,190));check(accepted==0&&picker.Result.IsEmpty,"lost pointer silently captured");}});
            run("core/selection resize uses final pointer and keyboard completion",delegate{using(var picker=new Picker(new Rectangle(0,0,320,220),true)){Rectangle accepted=Rectangle.Empty;picker.Accepted=delegate{accepted=picker.Result;};picker.Down(new Point(20,30));picker.Up(new Point(200,160));picker.Down(new Point(200,95));picker.Up(new Point(280,95));picker.Key(Keys.Enter);check(accepted==new Rectangle(20,30,260,130),"retained right handle lost final pointer");}});
            run("core/selection Escape cancels retained range",delegate{using(var picker=new Picker(new Rectangle(0,0,320,220),true)){int accepted=0;picker.Accepted=delegate{accepted++;};picker.Down(new Point(20,30));picker.Up(new Point(200,160));picker.Key(Keys.Escape);check(accepted==0&&picker.Result.IsEmpty,"cancel returned a selection");}});
            run("core/color loupe uses the frozen input without the clipboard",delegate{using(var picker=new Picker(new Rectangle(-320,0,320,220))){string value=null;picker.WriteColorToClipboard=delegate(string color){value=color;};picker.Key(Keys.C);picker.Down(new Point(100,100));check(value=="rgb(24, 123, 231)","wrong sample or output format");}});
            run("core/one hundred hidden selection paints erase every prior frame",delegate{using(var picker=new Picker(new Rectangle(0,0,480,320),true)){picker.Down(new Point(20,20));picker.Up(new Point(280,210));for(int i=0;i<100;i++){picker.Down(new Point(280,115));picker.MovePointer(new Point(281,115));picker.Up(new Point(280,115));using(var dirty=UiPaintingTests.NativePaint(picker,Color.Magenta))using(var clean=UiPaintingTests.NativePaint(picker,Color.Lime)){check(Hash(dirty)==Hash(clean),"old native pixels survived");if(i==99)dirty.Save(Path.Combine(output,"rewritten-picker-native.png"));}}check(!picker.Visible,"hidden test displayed picker");}});
            run("core/cancelled object drag preserves the existing redo branch",delegate{using(var editor=new Editor()){editor.AddAnnotation(ScreenCraftTests.Mark(Tool.Rect,50,50,200,160));editor.AddAnnotation(ScreenCraftTests.Mark(Tool.Ellipse,300,100,450,240));editor.Undo();editor.SelectAll();editor.Down(new Point(90,50));editor.MovePointer(new Point(120,80));editor.CancelGesture();check(editor.CanRedo&&editor.AnnotationCount==1&&editor.AnnotationSnapshot[0].A==new PointF(50,50),"cancel destroyed redo or original geometry");editor.Redo();check(editor.AnnotationCount==2,"redo branch lost");}});
            run("core/lost annotation capture rolls back without consuming an undo step",delegate{using(var editor=new Editor()){editor.AddAnnotation(ScreenCraftTests.Mark(Tool.Rect,50,50,200,160));editor.Down(new Point(90,50));editor.MovePointer(new Point(120,80));editor.LosePointer();check(editor.AnnotationSnapshot.Single().A==new PointF(50,50),"capture loss committed movement");editor.Undo();check(editor.AnnotationCount==0,"cancel left a phantom undo step");}});
            run("core/layered pin has real transparent corners and opaque source center",delegate{using(var image=new Bitmap(240,160)){using(var g=Graphics.FromImage(image))g.Clear(Color.Teal);using(var pin=PinWindow.CreateHidden(AnnotationDocument.FromImage(image),new Rectangle(0,0,1920,1080)))using(var surface=pin.SurfaceSnapshot()){check(surface.GetPixel(0,0).A==0,"opaque layered corner");var center=surface.GetPixel(surface.Width/2,surface.Height/2);check(center.A==255&&center.G==Color.Teal.G,"source color or premultiplication changed");surface.Save(Path.Combine(output,"rewritten-pin-layer.png"));check(!pin.Visible,"hidden pin became visible");}}});
            run("core/ambiguous repeated rows never append an arbitrary overlap",delegate{using(var stitcher=new Stitcher(96,120,0,500)){var first=new int[96*120];var next=new int[first.Length];for(int y=0;y<120;y++)for(int x=0;x<96;x++){first[y*96+x]=Color.FromArgb((y%8)*30,x*2,100).ToArgb();next[y*96+x]=Color.FromArgb(((y+4)%8)*30,x*2,100).ToArgb();}Stitcher.Result state;int added;stitcher.Add(first,out state,out added);stitcher.Add(next,out state,out added);check(state==Stitcher.Result.Lost&&added==0&&stitcher.Height==120,"ambiguous match corrupted output");}});
            run("core/background viewport and zoom keep image coordinates over the painted source",delegate{using(var editor=new Editor()){editor.InPlaceViewport=false;editor.Size=new Size(900,650);using(var g=Graphics.FromImage(editor.Img))g.FillRectangle(Brushes.Lime,280,180,60,60);editor.ApplyBackground(true,new Settings{BgKind=1,BgColor=0xCAD8E4,BgPadding=80,BgRatio="16:9",BgAlign=4});foreach(float factor in new[]{1f,1.25f}){editor.ZoomBy(factor);var point=editor.ImageToControl(new PointF(300,200));using(var image=UiPaintingTests.NativePaint(editor,Color.Magenta)){check(image.GetPixel(point.X,point.Y).G>245&&image.GetPixel(point.X,point.Y).R<10,"input coordinates no longer match composed image");}}}});
            run("core/editing shortcuts wait until the pointer transaction ends",delegate{using(var editor=new Editor()){editor.AddAnnotation(ScreenCraftTests.Mark(Tool.Rect,50,50,200,160));editor.Down(new Point(90,50));editor.MovePointer(new Point(120,80));editor.Key(Keys.Control|Keys.Z);check(editor.AnnotationCount==1&&editor.Busy,"undo changed a live drag");editor.Up(new Point(130,90));editor.Undo();check(editor.AnnotationCount==1&&editor.AnnotationSnapshot[0].A==new PointF(50,50),"drag no longer undoes atomically");}});
            run("core/large pin display budget includes its transparent margins",delegate{float limit=PinWindow.SurfaceZoomLimit(new Size(8000,8000),24);double pixels=(8000*limit+48)*(8000*limit+48);check(limit<1&&pixels<=24000005&&pixels>=23999000,"display allocation budget wrong");});
            run("core/shortcut codec rejects missing key numeric enum and duplicate key tokens",delegate{foreach(string text in new[]{"Ctrl","Ctrl++A","Ctrl+A+B","Ctrl+65535","Ctrl+LButton","Ctrl+Packet"}){uint mods;Keys key;check(!Hotkeys.TryParse(text,out mods,out key),"accepted "+text);}});
        }
        static string Hash(Bitmap image){using(var bytes=new MemoryStream()){image.Save(bytes,ImageFormat.Png);using(var hash=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(hash.ComputeHash(bytes.ToArray()));}}
    }
}
